/**
 * The data sources for fetching more information about a place.
 *
 * @remarks
 * It tells you which additional data is available for a place, and gives the IDs
 * that services need to fetch it.
 *
 * @example
 * ```typescript
 * const dataSources: PlaceDataSources = {
 *   geometry: { id: 'geom-456' }
 * };
 * ```
 *
 * @group Place
 */
type PlaceDataSources = {
  /**
   * The data source for the place's geometric shape.
   *
   * It is present on search results for places with geometric representations (type === Geography or POI).
   * Use its ID to fetch boundary polygons from the Geometry Data service. A reverse geocoded place
   * has none. To get one, search the place by name with its `geographyType`.
   *
   * @remarks
   * Use it to:
   * - Display administrative boundaries
   * - Show building footprints
   * - Visualize area coverage
   */
  geometry?: GeometryDataSource;
  /**
   * The data source for detailed POI information, which the Orbis places API doesn't return.
   *
   * @remarks
   * To fetch a place's details, pass the place's own `id` to `getPlaceDetails`.
   */
  poiDetails?: PoiDetailsDataSource;
};
/**
 * Data source reference for geometric shape data.
 *
 * @example
 * ```typescript
 * // Use this ID with the Geometry Data service
 * const dataSource: GeometryDataSource = {
 *   id: 'geom-abc123'
 * };
 * ```
 *
 * @group Place
 */
type GeometryDataSource = {
  /**
   * The geometry ID for the Geometry Data service.
   *
   * Pass it to fetch the geometric boundary (polygon or multipolygon)
   * of the place's shape on the map.
   */
  id: string;
};
/**
 * Data source reference for detailed POI information, which the Orbis places API doesn't return.
 *
 * @remarks
 * To fetch a place's details, pass the place's own `id` to `getPlaceDetails`.
 *
 * @group Place
 */
type PoiDetailsDataSource = {
  /**
   * The POI details ID.
   */
  id: string;
  /**
   * The name of the data provider for this POI, such as 'TomTom' or 'OSM'.
   *
   * Use it for attribution or quality assessment.
   */
  sourceName?: string;
};
