//#region src/types/place/poi/openingHours.d.ts
/**
 * A moment in time, with its date components pre-calculated so you don't need to parse the date.
 *
 * @example
 * ```typescript
 * const moment: Moment = {
 *   date: new Date(2025, 9, 20, 9, 30),
 *   dateYYYYMMDD: '2025-10-20',
 *   year: 2025,
 *   month: 10,
 *   day: 20,
 *   hour: 9,
 *   minute: 30
 * };
 * ```
 *
 * @group Place
 */
type Moment = {
  /**
   * The JavaScript Date of this moment.
   *
   * It holds the POI's local wall-clock time read in the runtime's time zone, not the instant. To tell
   * whether a POI is open now, compare against the current time in the POI's `timeZone`.
   */
  date: Date;
  /**
   * The date as a YYYY-MM-DD string, for display or comparison without time components.
   */
  dateYYYYMMDD: string;
  /**
   * The four-digit year, such as 2025.
   */
  year: number;
  /**
   * The month number (1-12).
   *
   * Note that unlike JavaScript Date.getMonth(), it is 1-based (January = 1).
   */
  month: number;
  /**
   * The day of the month (1-31).
   */
  day: number;
  /**
   * The hour in 24-hour format (0-23).
   */
  hour: number;
  /**
   * The minute (0-59).
   */
  minute: number;
};
/**
 * A period when a POI is open, with start and end moments.
 *
 * It can span multiple days, for example opening late one day and closing early the next.
 *
 * @remarks
 * For same-day hours, start and end are on the same date. For overnight hours, such as
 * open until 2 AM, the end date is after the start date.
 *
 * @example
 * ```typescript
 * // Monday 9:00 AM to 5:00 PM
 * const timeRange: TimeRange = {
 *   start: { date: new Date('2025-10-20T09:00:00'), hour: 9, minute: 0, ... },
 *   end: { date: new Date('2025-10-20T17:00:00'), hour: 17, minute: 0, ... }
 * };
 *
 * // Friday 10 PM to Saturday 2 AM (overnight)
 * const overnight: TimeRange = {
 *   start: { date: new Date('2025-10-24T22:00:00'), hour: 22, ... },
 *   end: { date: new Date('2025-10-25T02:00:00'), hour: 2, ... }
 * };
 * ```
 *
 * @group Place
 */
type TimeRange = {
  /**
   * The opening time of this period.
   */
  start: Moment;
  /**
   * The closing time of this period.
   */
  end: Moment;
};
/**
 * The time period that operating hours cover.
 *
 * Currently, only 'nextSevenDays' is supported, which gives the operating hours
 * for the upcoming week.
 *
 * @group Place
 */
type OpeningHoursMode = 'nextSevenDays';
/**
 * The operating hours of a POI, which say when it is open for business, including:
 * - Regular daily schedules
 * - Split shifts, such as lunch break closures
 * - Overnight hours
 * - 24/7 operation
 *
 * @remarks
 * Use it to:
 * - Display "Open now" / "Closed" status
 * - Show upcoming hours
 * - Determine if a location is open at a specific time
 * - Plan visits during operating hours
 *
 * @example
 * ```typescript
 * const openingHours: OpeningHours = {
 *   mode: 'nextSevenDays',
 *   timeRanges: [
 *     { start: {...}, end: {...} },  // Monday
 *     { start: {...}, end: {...} }   // Tuesday
 *   ],
 *   alwaysOpenThisPeriod: false
 * };
 *
 * // 24/7 location
 * const alwaysOpen: OpeningHours = {
 *   mode: 'nextSevenDays',
 *   timeRanges: [{ start: {...}, end: {...} }],  // 00:00 to 00:00
 *   alwaysOpenThisPeriod: true
 * };
 * ```
 *
 * @group Place
 */
type OpeningHours = {
  /**
   * The time period the hours cover, currently always 'nextSevenDays'.
   */
  mode: OpeningHoursMode;
  /**
   * The time ranges when the POI is open, one per opening period.
   *
   * Multiple ranges per day mean split shifts, such as closing for lunch.
   * If `alwaysOpenThisPeriod` is true, it holds one range spanning the period, midnight to midnight.
   */
  timeRanges: TimeRange[];
  /**
   * Whether the POI is always open during the requested period.
   *
   * If true, the location operates 24/7 and `timeRanges` holds that one range.
   * Otherwise, `timeRanges` holds the specific open hours.
   */
  alwaysOpenThisPeriod: boolean;
};
//#endregion
//#region src/types/place/poi/poi.d.ts
/**
 * The Point of Interest (POI) details of a place such as a business, landmark or facility.
 *
 * They add operational details and categorization to the basic place information.
 *
 * @example
 * ```typescript
 * const poi: POI = {
 *   name: 'Central Station Café',
 *   phone: '+31 20 123 4567',
 *   brands: ['Starbucks'],
 *   categories: ['CAFE'],
 *   localizedCategories: ['café'],
 *   url: 'https://example.com',
 *   openingHours: { mode: 'nextSevenDays', timeRanges: [...], alwaysOpenThisPeriod: false }
 * };
 * ```
 *
 * @group Place
 */
type POI = {
  /**
   * The primary display name of the POI, localized in the request language.
   */
  name: string;
  /**
   * The contact phone number of the POI, typically with the country code, such as '+31 20 123 4567'.
   */
  phone?: string;
  /**
   * The brand names of this POI, such as 'Starbucks', 'Shell' or 'Marriott' for chain locations.
   */
  brands?: string[];
  /**
   * The URL of the official website or online presence of the business or location.
   */
  url?: string;
  /**
   * The standardized category identifiers of the POI.
   *
   * They are machine-readable names from the {@link POICategory} enum, such as `'ITALIAN_RESTAURANT'`,
   * `'FUEL_STATION'` or `'HOTEL'`, parsed from the numeric category IDs the API returns.
   * Use them for filtering, programmatic category matching or mapping to icons.
   */
  categories: POICategory[];
  /**
   * The human-readable category names of the POI, as the API returns them, such as `'italian'`,
   * `'restaurant'`, `'petrol station'` or `'hotel'`.
   *
   * They are in English, the same whatever the request `language`. For names in that language, look
   * up each of {@link categories} by `code` in what `getPOICategories` returns for it. A few of those
   * names are identifiers, such as `'GeneralHospitalAndPolyclinic'`: keep these English names there.
   */
  localizedCategories: string[];
  /**
   * When the POI is open, including daily schedules and special hours.
   *
   * Use it to tell whether a location is currently open, or to plan visits.
   */
  openingHours?: OpeningHours;
  /**
   * The time zone of the POI location, for interpreting opening hours and scheduling
   * visits across time zones.
   */
  timeZone?: TimeZone;
};
/**
 * A reference to a related Point of Interest, in a parent-child relationship such as:
 * - A restaurant inside a shopping mall
 * - A store within an airport terminal
 * - A department within a larger facility
 *
 * @example
 * ```typescript
 * const relatedPOI: RelatedPOI = {
 *   relationType: 'parent',  // This POI is inside a larger complex
 *   id: 'abc123def456'       // ID to fetch parent POI details
 * };
 * ```
 *
 * @group Place
 */
type RelatedPOI = {
  /**
   * How this POI relates to the referenced one.
   *
   * - `child`: The referenced POI is contained within this POI (e.g., a store in this mall)
   * - `parent`: This POI is contained within the referenced POI (e.g., this store is inside a mall)
   */
  relationType: 'child' | 'parent';
  /**
   * The unique identifier of the related POI.
   *
   * Pass it to the Place by ID service to fetch detailed information
   * about the related location.
   */
  id: string;
};
//#endregion
