/**
 * A GeoJSON FeatureCollection of the places that search or geocoding operations return.
 *
 * @typeParam P - Type of individual place properties (defaults to CommonPlaceProps)
 * @typeParam FeatureCollectionProps - Type of collection-level properties
 *
 * @example
 * ```typescript
 * const places: Places<SearchPlaceProps> = {
 *   type: 'FeatureCollection',
 *   features: [
 *     { id: '1', type: 'Feature', geometry: {...}, properties: {...} },
 *     { id: '2', type: 'Feature', geometry: {...}, properties: {...} }
 *   ]
 * };
 * ```
 *
 * @group Place
 */
export type Places<P extends CommonPlaceProps = CommonPlaceProps, FeatureCollectionProps = unknown> = Omit<FeatureCollectionWithProperties<Point, P, FeatureCollectionProps>, 'features' | 'bbox'> & {
  /**
   * The bounding box of all the places, including their own bounding boxes.
   * It is present only if there are places.
   */
  bbox?: BBox;
  /**
   * The place features, each with a required string ID.
   */
  features: Place<P>[];
};
