//#region src/util/curves.d.ts
/**
 * Finds the curves of a route: the stretches where the road keeps turning the same way.
 *
 * @param route The route, with its geometry, and its guidance instructions when it has them.
 * @param options The thresholds a stretch has to reach to count as a curve.
 * @returns The curves, in order along the route.
 *
 * @remarks
 * - `calculateRoute` fills `sections.curve` when its `sectionTypes` names `curve`, with these
 *   thresholds from its `curveDetection.curve`. Call this, or {@link withCurveSections}, to find
 *   them again with others.
 * - A curve ends at a straight longer than `maxStraightInMeters`, or where the road turns the
 *   other way, so an S-bend is two curves.
 * - A sharp corner between two straights, as at most junctions, is no curve: the road doesn't bend
 *   there. A roundabout is, and on a route with guidance a curve at a junction names its
 *   `maneuver`, as {@link CurveSectionProps} sets out.
 * - Where a route turns back at a waypoint, as at the end of a dead-end road, it makes no curve.
 * - Each curve's `severity` reads the route's `speedLimit` sections, when it has them.
 *
 * @example
 * ```typescript
 * // Only the hard curves, to warn a passenger prone to motion sickness
 * const hard = getCurveSections(route, { maxRadiusInMeters: 50, minHeadingChangeInDegrees: 60 });
 * ```
 *
 * @group Utils
 */
export declare const getCurveSections: (route: Route, { minHeadingChangeInDegrees, maxRadiusInMeters, maxStraightInMeters }?: CurveSectionsOptions) => CurveSectionProps[];
/**
 * Whether a curve is a hairpin: a bend of the road turning 140° or more on a radius of 40 m or less,
 * as the numbered bends of a mountain pass do.
 *
 * @remarks
 * - A wider bend that turns as far, as where a valley road swings round a spur, is a horseshoe a
 *   driver takes at speed, and no hairpin.
 * - A curve at a maneuver, as a roundabout or a turn at a junction, is no hairpin however far it
 *   turns.
 * - A curvy stretch's `hairpinCount` counts its curves this says yes to.
 *
 * @example
 * ```typescript
 * const hairpins = route.properties.sections.curve?.filter(isHairpin) ?? [];
 * ```
 *
 * @group Utils
 */
export declare const isHairpin: (curve: Pick<CurveSectionProps, "headingChangeInDegrees" | "radiusInMeters" | "maneuver">) => boolean;
/**
 * Finds the curvy stretches of a route: where curves follow one another closely, such as a
 * mountain pass or a winding country road.
 *
 * @param route The route, with its geometry.
 * @param options The curves to group, and how close they have to follow one another.
 * @returns The curvy stretches, in order along the route.
 *
 * @remarks
 * - `calculateRoute` fills `sections.curvyStretch` when its `sectionTypes` names `curvyStretch`,
 *   with these thresholds from its `curveDetection.curvyStretch`. Call this for others, or over
 *   curves you found with your own {@link getCurveSections} thresholds.
 * - A curve at a maneuver ends a stretch, as {@link CurvyStretchSectionProps} sets out.
 * - A stretch's `curveCount` over its `lengthInMeters` says how winding it is: the hairpins of a
 *   mountain pass come one every 200 m or so. Rank the stretches by it to seek out the best roads, or
 *   to tell which route stays clear of them. Its `hairpinCount` says how many of them are hairpins,
 *   as {@link isHairpin} tells them.
 * - Its `curvinessScore` adds up its curves' scores, so a longer stretch scores more. Roadcurvature.com,
 *   which scores roads the same way, lists them from 300 and calls those over 1000 very twisty.
 *
 * @example
 * ```typescript
 * const routes = await calculateRoute({ locations, costModel: { routeType: 'thrilling' }, guidance: { type: 'coded' } });
 * const passes = getCurvyStretchSections(routes.features[0], { minCurveCount: 5 });
 * passes.forEach((pass) => console.log(`${pass.curveCount} curves in ${formatDistance(pass.lengthInMeters)}`));
 *
 * // The most rewarding stretch to ride
 * const best = passes.toSorted((first, second) => second.curvinessScore - first.curvinessScore)[0];
 * ```
 *
 * @group Utils
 */
export declare const getCurvyStretchSections: (route: Route, { curves, maxGapInMeters, minCurveCount }?: CurvyStretchSectionsOptions) => CurvyStretchSectionProps[];
/**
 * A copy of a route with its curves and curvy stretches found again, with thresholds of your own.
 *
 * @param route The route, with its geometry, and its guidance instructions when it has them.
 * @param options The thresholds, `calculateRoute`'s `curveDetection` among them.
 * @returns The route with new `sections.curve` and `sections.curvyStretch`, each left out when it
 * finds none. Its other sections stay as they are.
 *
 * @remarks
 * - Tune the thresholds on routes you already have, with no new request. Calling
 *   {@link getCurveSections} and {@link getCurvyStretchSections} yourself does the same, as long as
 *   you pass the new curves to the second.
 * - The curves read the route as it came back: a `maneuver` needs its guidance, and a `severity`
 *   its `speedLimit` sections. Ask for both when you calculate it.
 *
 * @example
 * ```typescript
 * // Count the sweeping bends of up to 500 m too
 * const wider = routes.features.map((route) => withCurveSections(route, { curve: { maxRadiusInMeters: 500 } }));
 * await routingModule.showRoutes({ ...routes, features: wider });
 * ```
 *
 * @group Utils
 */
export declare const withCurveSections: (route: Route, { curve, curvyStretch }?: CurveDetectionOptions) => Route;
//#endregion
